// Furniture catalog (data only). Meshes are generated by build/FurnitureCatalog.js
// from `shape` + `p` (parameters), so adding an item is one line here.
//
//  w, d    footprint in metres (multiples of 0.5; front faces +Z)
//  h       collision height (0 = walk-over, e.g. rugs)
//  style   style points added to the home's style score
//  use     activity offered when the player interacts (see sim/Activities.js)
//  q       quality multiplier for that activity (beds: energy/hour, etc.)
//  wall    must stand against a wall         light  adds a warm light at night
//  shop    only used by commercial interiors (not sold)

const F = (id, name, cat, price, w, d, h, style, shape, extra = {}) => ({ id, name, cat, price, w, d, h, style, shape, ...extra });

